from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

select_cva = cva(
    base="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
    variants={
        "variant": {
            "default": "",
            "error": "border-destructive",
        },
        "size": {
            "sm": "h-9 text-sm",
            "default": "h-10 text-sm",
            "lg": "h-11 text-base",
        },
    },
    default_variants={
        "variant": "default",
        "size": "default",
    }
)

class SelectNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        final_class = select_cva(**resolved_kwargs)

        known_args = ["variant", "size", "label", "error", "help_text", "name", "id", "disabled", "required", "class", "class_name", "slot"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        slot = self.nodelist.render(context) if self.nodelist else ""
        label = resolved_kwargs.get("label", "")
        error = resolved_kwargs.get("error", "")
        help_text = resolved_kwargs.get("help_text", "")
        name = resolved_kwargs.get("name", "")
        id_val = resolved_kwargs.get("id", "")
        disabled = resolved_kwargs.get("disabled", False)
        required = resolved_kwargs.get("required", False)

        t = context.template.engine.get_template('components/select.html')
        new_context = context.new({
            "class": final_class,
            "attrs": attrs,
            "label": label,
            "error": error,
            "help_text": help_text,
            "name": name,
            "id": id_val,
            "disabled": disabled,
            "required": required,
            "slot": slot,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_select')
def djinn_select(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_select',))
    parser.delete_first_token()
    return SelectNode(nodelist, kwargs)
